const __pageData = JSON.parse('{"title":"Right Sidebar","description":"","frontmatter":{"editSource":"docs/subsystems/sidebar-right.md","rawMarkdownPath":"en/reference/subsystems/sidebar-right.md","outline":[2,3]},"headers":[],"relativePath":"en/reference/subsystems/sidebar-right.md","filePath":"en/reference/subsystems/sidebar-right.md"}');
